let desktopStorageCache=null,desktopStartupState=null,desktopStorageLoading=null,desktopWriteQueue=Promise.resolve();
function readBrowserStorage(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")}catch{return{}}}
function mergeStoredRows(legacyRows,desktopRows){const merged=[],positions=new Map();for(const row of [...(Array.isArray(legacyRows)?legacyRows:[]),...(Array.isArray(desktopRows)?desktopRows:[])]){if(!row||typeof row!=="object"||Array.isArray(row))continue;const key=String(row.id||"").trim();if(key&&positions.has(key)){const index=positions.get(key);merged[index]={...merged[index],...row};continue}if(key)positions.set(key,merged.length);merged.push(row)}return merged}
async function readStorage(){
  if(!window.remiDesktop?.load)return readBrowserStorage();
  if(desktopStorageCache)return desktopStorageCache;
  if(!desktopStorageLoading)desktopStorageLoading=(async()=>{
    const browserData=readBrowserStorage();
    desktopStartupState=await window.remiDesktop.load()||{};
    const saved=desktopStartupState&&typeof desktopStartupState==="object"&&!Array.isArray(desktopStartupState)?desktopStartupState:{};
    const legacy=browserData&&typeof browserData==="object"&&!Array.isArray(browserData)?browserData:{};
    desktopStorageCache={...legacy,...saved};
    desktopStorageCache.programs=mergeProgramRecords(legacy.programs,saved.programs);
    desktopStorageCache.demos=mergeStoredRows(legacy.demos,saved.demos);
    // Never rewrite the multi-megabyte workspace during boot. The merged view
    // remains available immediately and the next explicit edit persists it.
    return desktopStorageCache;
  })();
  return desktopStorageLoading;
}
