function languageName(){return ({fr:"French",es:"Spanish",de:"German",pt:"Portuguese"})[uiLanguage]||"English"}
function localizedPrompt(prompt){const language=languageName();return `Write every user-facing string in ${language}, including replies, suggestions, navigation guidance, step instructions, outcomes, status text, and review notes. Keep exact website control labels in their original language when quoting them. Do not mix languages except for those exact labels. ${prompt}`}
function translateTextNode(node,index){if(!uiTextSources.has(node))uiTextSources.set(node,node.data);const original=uiTextSources.get(node),trimmed=original.trim(),row=UI_TRANSLATIONS[trimmed];if(!row)return;const translated=uiLanguage==="en"?trimmed:row[index];if(!translated)return;const left=original.match(/^\s*/)?.[0]||"",right=original.match(/\s*$/)?.[0]||"",value=left+translated+right;if(node.data!==value)node.data=value}
function translateUi(root=document.body){if(root===document.body&&document.documentElement.lang!==uiLanguage)document.documentElement.lang=uiLanguage;const index=({fr:0,es:1,de:2,pt:3})[uiLanguage];if(root.nodeType===Node.TEXT_NODE){translateTextNode(root,index);return}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))translateTextNode(node,index);const selector="input,textarea,button,[aria-label],[title],option",elements=[];if(root.nodeType===Node.ELEMENT_NODE&&root.matches(selector))elements.push(root);elements.push(...root.querySelectorAll(selector));for(const el of elements){let originals=uiAttrSources.get(el);if(!originals){originals=new Map();uiAttrSources.set(el,originals)}for(const attr of ["placeholder","aria-label","title"]){if(!el.hasAttribute(attr))continue;if(!originals.has(attr))originals.set(attr,el.getAttribute(attr));const value=originals.get(attr),row=UI_TRANSLATIONS[value],translated=row?(uiLanguage==="en"?value:row[index]):null;if(translated&&el.getAttribute(attr)!==translated)el.setAttribute(attr,translated)}if(el.tagName==="OPTION"){if(!originals.has("text"))originals.set("text",el.textContent);const value=originals.get("text"),row=UI_TRANSLATIONS[value];if(row){const text=uiLanguage==="en"?value:row[index];if(text&&el.textContent!==text)el.textContent=text}}}}async function updateUiLanguage(){const select=$("ui-language");if(uiLanguageMode!=="auto"){uiLanguage=["en","fr","es","de","pt"].includes(uiLanguageMode)?uiLanguageMode:"en";if(select)select.value=uiLanguage;translateUi();renderSuggestions();updateFullscreenLabel();if(!$("view-settings").hidden)renderKnowledge();return}try{await refreshTab()}catch{}const prefix=String(currentTab?.lang||"en").toLowerCase().split("-")[0];uiLanguage=["fr","es","de","pt"].includes(prefix)?prefix:"en";translateUi();renderSuggestions();updateFullscreenLabel();if(!$("view-settings").hidden)renderKnowledge();if(select)select.value="auto"}
$("ui-language")?.addEventListener("change",async event=>{const choice=event.currentTarget.value;uiLanguageMode=["auto","en","fr","es","de","pt"].includes(choice)?choice:"auto";await chrome.storage.local.set({uiLanguageMode});await updateUiLanguage()});
new MutationObserver(records=>{const changed=new Set();for(const record of records){if(record.type==="characterData")changed.add(record.target);else for(const node of record.addedNodes)if(node.nodeType===Node.ELEMENT_NODE||node.nodeType===Node.TEXT_NODE)changed.add(node)}for(const root of changed)translateUi(root)}).observe(document.body,{subtree:true,childList:true,characterData:true});

let toastTimer=0;function showToast(message,bad=false,duration=3600){const toast=$("remi-toast");if(!toast||!message)return;toast.textContent=message;toast.classList.toggle("error",bad);toast.hidden=false;toast.classList.remove("leaving");clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.classList.add("leaving");setTimeout(()=>{toast.hidden=true;toast.classList.remove("leaving")},220)},duration)}function setMessage(id, message, bad=false) { const row=UI_TRANSLATIONS[message];if(row&&uiLanguage!=="en")message=row[["fr","es","de","pt"].indexOf(uiLanguage)]||message;const el=$(id); if(!el)return; el.textContent=message; el.classList.toggle("error",bad);if(!bad&&/\b(saved|connected|complete|completed|finished|downloaded|selected|added to the shared library|synced|batch saved|guide saved|demo saved|approved action sent)\b/i.test(message))showToast(message); }
const loginNotice=$("program-learning-message");if(loginNotice)new MutationObserver(()=>{$("login-handoff").hidden=!/sign.?in|login|connexion|inicio de sesi[oó]n|anmeld/i.test(loginNotice.textContent)}).observe(loginNotice,{childList:true,characterData:true,subtree:true});$("login-handoff")?.addEventListener("click",async()=>{if(window.remiDesktop?.focusSelected){setBarExpanded(false);const result=await window.remiDesktop.focusSelected();if(!result.ok&&currentTab?.url&&/^https:\/\//i.test(currentTab.url)){window.remiDesktop.openUrl(currentTab.url);setMessage("program-learning-message","Opened the sign-in page in your browser. Sign in yourself, then return and choose Resume.")}else if(!result.ok)setMessage("program-learning-message",result.reason||"Choose the browser window with the login page, then try again.",true);else setMessage("program-learning-message","The sign-in page is in front. Sign in yourself, then return and choose Resume.")}else if(currentTab?.url){window.open(currentTab.url,"_blank","noopener");setMessage("program-learning-message","The sign-in page is open. Sign in yourself, then return and choose Resume.")} });
function friendlyError(error, options={}) { const raw=error?.message||String(error),s=raw.replace(/\b(?:sk|rk|nvapi)[-_][A-Za-z0-9_-]{12,}\b/gi,"[redacted API key]").replace(/(Bearer\s+)\S+/gi,"$1[redacted]"); if(error?.status===422||/422|content safety|content_safety|safety screening/i.test(s))return "NVIDIA safety screening blocked AI analysis of this page (HTTP 422). This is not a key or connection error. Your progress is saved. In the in-app browser, Remi will retry using text and controls only, then skip the page if NVIDIA still refuses it. For a separately selected browser window, move to another page yourself, then click Resume."; if(/401|unauthorized|invalid api key|incorrect api key|authentication/i.test(s)){if(error?.provider==="nvidia"){const detail=s.replace(/^API 401(?:\s*\([^)]*\))?:?\s*/i,"").slice(0,320);return "NVIDIA rejected the API key (HTTP 401). Check that the new key is active, copied fully, and created under the NVIDIA account. Keep Provider set to NVIDIA and use https://integrate.api.nvidia.com/v1/chat/completions. Provider response: "+detail+" The key has been hidden from this message."}return "The selected provider rejected this API key. In Settings, check that it is active and belongs to the selected provider. The key itself has been hidden from this message."} if(/either the.*all_urls.*activeTab.*permission is required|captureVisibleTab.*permission/i.test(s))return "Chrome blocked Self-Learning screenshot capture. Reload Remind-er 3 version 3.3.3 and allow access to all websites in the extension permission prompt."; const nvidiaDenied=error?.provider==="nvidia"&&(error?.status===403||/403|forbidden|access denied|model_access_denied|not found for account|not available to your account/i.test(s)); if(nvidiaDenied){let message="NVIDIA denied access to this model or endpoint. In Settings, choose a model enabled for your NVIDIA key, then test again.";if(options.sessionSaved)message+=" Your Self-Learning session is saved; resume after the provider grants access.";return message} if(/403|forbidden|permission|access denied|model_access_denied/i.test(s)){const detail=s.replace(/^API 403(?:\s*\([^)]*\))?:?\s*/i,"").slice(0,500);return "The provider denied this request. Check the provider, model access, and endpoint in Settings. Provider response: "+detail+(options.sessionSaved?" Your Self-Learning session is saved; resume after the provider grants access.":"");} if(error?.provider==="nvidia"&&(error?.status===404||/404|model_not_found|model.*not found/i.test(s))){const detail=s.replace(/^API 404\s+provider\s+nvidia\s+model\s+\S+\s+endpoint\s+\S+\s*:?\s*/i,"").slice(0,420);if(/same key.{0,100}lists this model/i.test(detail))return "NVIDIA accepted the key and lists this model, but its inference request returned 404. This points to NVIDIA hosted Public API Endpoints access for the account, not an incorrect model name. Check the NVIDIA Build Playground; if it works there, contact help@build.nvidia.com and ask them to check Public API Endpoints access. Do not share the full API key."+(options.sessionSaved?" Your Self-Learning session is saved; resume after NVIDIA resolves access.":"");if(/not found for account|function.{0,30}not found/i.test(detail))return "NVIDIA returned 404: "+detail+" This points to NVIDIA account access for hosted Public API Endpoints, rather than a Remind-er connection problem. Check that your NVIDIA Build account is verified and that API inference works in its Playground. If Playground works but this API call still returns 404, contact help@build.nvidia.com and ask them to check Public API Endpoints access. Do not send your full API key."+(options.sessionSaved?" Your Self-Learning session is saved; resume after NVIDIA enables access.":"");return "NVIDIA returned 404"+(detail?": "+detail: ". Check the selected model and endpoint.")+" The default model ID is listed on NVIDIA Build, but your key may not have access to it. Choose a model enabled for your key in Settings. Verify the endpoint is https://integrate.api.nvidia.com/v1/chat/completions."+(options.sessionSaved?" Your Self-Learning session is saved; resume after correcting Settings.":"")} if(error?.provider==="nvidia"&&error?.status===404)return "NVIDIA returned HTTP 404. The official endpoint is set and NVIDIA lists this model, but the saved API key may not have access. Open the selected model page on NVIDIA Build, generate a key for its hosted API, and replace the saved key in Remind-er Settings. Or choose a model listed for your current key. Provider response: "+s.slice(0,220); if(/404|model_not_found|model.*not found/i.test(s))return "The API endpoint or model was not found. Check the API address and model name in Settings. Provider response: "+s.slice(0,420); if(/429|rate.?limit|quota|billing/i.test(s))return "The API account reached a usage or rate limit. Check its limits and billing, then try again."; if(/Failed to fetch|NetworkError|ERR_CONNECTION/i.test(s))return "Can’t reach the AI provider. Check your connection and the API address in Settings."; return s; }
