function localizedUiText(text){const row=UI_TRANSLATIONS[text];return row&&uiLanguage!=='en'?row[['fr','es','de','pt'].indexOf(uiLanguage)]||text:text}
async function refreshApiConnectionCard(){const provider=$('api-provider').value,keyName=provider==='nvidia'?'nvidiaApiKey':'apiKey',saved=await chrome.storage.local.get([keyName,'lastAIConnectionTest']),key=String(saved[keyName]||'').trim(),entered=String($('api-key').value||'').trim(),status=$('api-key-status'),card=$('api-test-result'),result=$('api-test-result-text'),label='Saved key for '+(provider==='nvidia'?'NVIDIA':'OpenAI')+': '+(key?'Yes (hidden)':'No');status.textContent=localizedUiText(label)+(entered&&entered!==key?' · '+localizedUiText('New key entered but not saved'):'');const last=saved.lastAIConnectionTest;if(last&&last.provider===provider){const when=last.checkedAt?new Date(last.checkedAt).toLocaleString(uiLanguage):'';card.dataset.state=last.ok?'success':'error';result.textContent=localizedUiText(last.ok?'Connected':'Connection failed')+(when?' · '+when:'')+(last.message?' · '+last.message:'')}else{card.dataset.state='idle';result.textContent=localizedUiText('No connection test run yet for this provider.')}}async function loadProviderSettings(provider){const local=await chrome.storage.local.get(["apiKey","apiEndpoint","apiModel","nvidiaApiKey","nvidiaApiEndpoint","nvidiaApiModel"]),disk=window.remiDesktop?(desktopStorageCache||desktopStartupState||{}):{};if(provider==="nvidia"){$("api-key").value=Object.hasOwn(local,"nvidiaApiKey")?local.nvidiaApiKey:(disk.nvidiaApiKey||"");$("api-endpoint").value=local.nvidiaApiEndpoint||disk.nvidiaApiEndpoint||NVIDIA_API_DEFAULT;const model=Object.hasOwn(local,"nvidiaApiModel")?local.nvidiaApiModel:disk.nvidiaApiModel,nvidiaModel=model==="mistralai/mistral-large-4-1t-a52b"?NVIDIA_MODEL_DEFAULT:(model||NVIDIA_MODEL_DEFAULT);$("api-model").value=nvidiaModel;if(model==="mistralai/mistral-large-4-1t-a52b")await chrome.storage.local.set({nvidiaApiModel:nvidiaModel})}else{$("api-key").value=Object.hasOwn(local,"apiKey")?local.apiKey:(disk.apiKey||"");$("api-endpoint").value=local.apiEndpoint||disk.apiEndpoint||API_DEFAULT;$("api-model").value=local.apiModel||disk.apiModel||"gpt-6-luna"}$("api-endpoint").placeholder=provider==="nvidia"?NVIDIA_API_DEFAULT:API_DEFAULT;$("api-model").placeholder=provider==="nvidia"?NVIDIA_MODEL_DEFAULT:"Model ID"}
async function persistAIProviderSettings(values){const stamped={...values,aiProviderSettingsUpdatedAt:Date.now()};await chrome.storage.local.set(stamped);return stamped}
$("api-provider").addEventListener("change",()=>{const provider=$("api-provider").value;providerSettingsReady=(async()=>{const key=$("api-key"),endpoint=$("api-endpoint"),model=$("api-model");key.value="";endpoint.value="";model.value="";setMessage("settings-message","Loading "+(provider==="nvidia"?"NVIDIA":"OpenAI")+" settings…");await loadProviderSettings(provider);await refreshApiConnectionCard()})();updateTutorResearchAvailability()});
function updateTutorResearchAvailability(){const input=$("tutor-research"),note=$("tutor-context-note");if(!input||!note)return;const openai=$("api-provider").value==="openai";input.disabled=!openai;note.textContent=openai?"Remi can use the current page for context. Optional live web research sends your question to OpenAI and may add API charges.":"Remi can use the current page for context. Live web research is available only when OpenAI is selected."}
$("save-settings").addEventListener("click",async()=>{try{const provider=$("api-provider").value,endpoint=$("api-endpoint").value.trim(),u=new URL(endpoint),shared=readSharedDbFields();if(u.protocol!=="https:")throw new Error("Use a secure HTTPS API address.");if(Boolean(shared.url)!==Boolean(shared.key))throw new Error("Add both the shared Supabase URL and publishable key, or leave both blank.");if(shared.url){validateSharedDbUrl(shared.url);if(!await requestApiPermission(shared.url))throw new Error("Allow Remind-er to connect to the shared demo library.")}const allowed=await requestApiPermission(endpoint);if(!allowed)throw new Error("Allow access to this AI provider’s API address to continue.");const prior=await chrome.storage.local.get(["sharedDemoDbUrl","sharedDemoDbKey"]),changed=prior.sharedDemoDbUrl!==shared.url||prior.sharedDemoDbKey!==shared.key,sharedSettings={sharedDemoDbUrl:shared.url,sharedDemoDbKey:shared.key};if(changed)await chrome.storage.local.remove("sharedDemoDbSession");const providerSettings=provider==="nvidia"?{apiProvider:provider,nvidiaApiKey:$("api-key").value.trim(),nvidiaApiEndpoint:endpoint,nvidiaApiModel:$("api-model").value.trim()||NVIDIA_MODEL_DEFAULT}:{apiProvider:provider,apiKey:$("api-key").value.trim(),apiEndpoint:endpoint,apiModel:$("api-model").value.trim()||"gpt-6-luna"};await persistAIProviderSettings({...sharedSettings,...providerSettings});setMessage("settings-message","Saved on this device. Remi now connects directly to "+(provider==="nvidia"?"NVIDIA.":"OpenAI."));await refreshApiConnectionCard();await renderIdleWorkSetting();scheduleIdlePreparation(0);if(shared.url)setMessage("shared-library-message","Shared database settings saved. Use Connect and test shared library to finish setup.")}catch(e){setMessage("settings-message",friendlyError(e),true)}});
