async function makeDemo(){
 const button=$("make-demo"),p=chosenProgram("demo-program"),req=$("demo-request").value.trim();
 if(!p){setMessage("demo-message","Choose a saved program or website first.",true);return}
 if(!req){setMessage("demo-message","Enter the task Remi should demonstrate.",true);return}
 if(!$("demo-consent").checked){setMessage("demo-message","Please agree before Remi sends saved screenshots for analysis.",true);return}
 if(await recallMatchingDemo(p,req))return;
 if(!demoConfirmed){try{button.disabled=true;setMessage("demo-message","Remi is checking the request. Please wait.");const understood=await apiCall(localizedPrompt(INTENT_PROMPT),{question:req,program:{name:p.name,kind:p.kind,version:p.version},task:"Restate the likely demo goal in one short sentence; do not answer."});pendingDemoRequest=req;$("demo-confirm-text").textContent=askConfirmationText(String(understood.understood_as||req));$("demo-confirm").hidden=false;setMessage("demo-message","Confirm or correct the task Remi understood.")}catch(error){setMessage("demo-message",friendlyError(error),true)}finally{button.disabled=false}return}
 if(req!==pendingDemoRequest){demoConfirmed=false;$("demo-confirm").hidden=true;setMessage("demo-message","The task changed. Choose Build a demo again so Remi can confirm the new request.",true);return}
 demoConfirmed=false;$("demo-confirm").hidden=true;
 try{button.disabled=true;setMessage("demo-message","Preparing saved screenshots for the demo…");
  const evidence=selectDemoEvidence(p,req,12);if(!evidence.length){const panel=$("demo-evidence-request");if(panel){panel.hidden=false;$("demo-evidence-task").textContent=req;const list=$("demo-evidence-checklist");if(list)list.replaceChildren(...["Show the title or landing page.","Navigate through each page or tab needed for this task.","Show the exact control and the result after using it.","Finish on the requested final page or step."].map(text=>{const li=document.createElement("li");li.textContent=text;return li}))}throw new Error("This profile has no saved screenshots yet. Add a short recording or run Self-Learning for this profile, then build the demo again.")}
  const safe=await prepareIdleScreens(evidence,"demo evidence for "+p.name);if(!safe.length)throw new Error("No saved screenshot could be prepared safely. Add clearer screenshots to this profile and retry.");
  const assets=safe.map((x,i)=>({type:"image/jpeg",data:x.data,name:"demo-screen-"+(i+1)+".jpg"})),frame_context=safe.map((x,i)=>({frame:i,page:x.context?.page||x.context?.title||"",source:p.name,browser_chrome_cropped:true,email_masking:"Review visible pixels for personal information."})),programContext={name:p.name,kind:p.kind,version:p.version,guide:p.guide||"",tasks:p.tasks||[],site_map:p.siteMap||[],common_uses:p.commonUses||[],remi_review_instructions:p.remiReviewInstructions||[]};
  setMessage("demo-message","Remi is building and checking the demo against "+assets.length+" saved screenshots…");const draft=await apiCall(localizedPrompt(DEMO_PROMPT),{request:req,desired_final_page_or_step:"Start at the title or landing page when available, show verified page changes in order, and finish on the requested destination only when evidence supports it.",navigation_rule:DEFAULT_DEMO_NAVIGATION_RULE,program:programContext,frame_context,evidence_notes:p.sources||[]},assets);if(!Array.isArray(draft.steps)||!draft.steps.length)throw new Error(draft.notes||"The saved screenshots do not show this task yet. Add material that shows the steps and final page.");
  const reviewed=await apiCall(localizedPrompt(DEMO_REVIEW_PROMPT),{request:req,desired_final_page_or_step:"Keep only screenshot-verified steps, preserve navigation order and end at the requested destination when shown.",program:programContext,frame_context,draft:{title:draft.title,notes:draft.notes,gaps:draft.gaps,steps:draft.steps.slice(0,10)}},assets);let steps=normalizeDemoSteps(reviewed.steps||draft.steps,assets.length);steps=await repairDemoCursorCoordinates(steps,assets,req,p.name);if(!steps.length)throw new Error("Remi could not verify usable steps from these screenshots. The draft was not saved.");
  const saved={...draft,...reviewed,id:crypto.randomUUID(),steps,programId:p.id,frameProgramId:p.id,program:p.name,version:p.version||"version not provided",request:req,language:uiLanguage,createdAt:new Date().toISOString(),evidenceIndexes:evidence.map(x=>x.index),evidenceFingerprints:evidence.map(x=>frameFingerprint(x.data)),privacyCropped:true,stepsUseCroppedFrame:true,verified:false};delete saved.frames;demos.push(saved);demos=demos.slice(-500);await chrome.storage.local.set({demos});renderDemoList();renderSuggestions();const index=demos.length-1;await showDemo(index);setMessage("demo-message","Demo saved and checked against the profile screenshots. Final step: "+String(steps.at(-1)?.screen||steps.at(-1)?.target||"last verified screen")+".");
  const db=await chrome.storage.local.get(["sharedDemoDbUrl","sharedDemoDbKey"]);if(db.sharedDemoDbUrl&&db.sharedDemoDbKey){try{await publishSharedDemo(saved,p);await chrome.storage.local.set({demos});setMessage("demo-message","Demo saved locally and added to the shared library.")}catch(error){setMessage("demo-message","Demo saved locally, but shared sync failed: "+friendlyError(error),true)}}
 }catch(error){setMessage("demo-message",friendlyError(error),true)}finally{button.disabled=false}
}
